import { twMerge } from "../lib/tw";

/** The ring, the orange time arc and the pivot, shared by mark and loader. */
function Clock() {
  return (
    <>
      <circle
        cx="32"
        cy="32"
        r="19"
        fill="none"
        strokeWidth="6"
        className="stroke-primary"
      />
      <path
        d="M22.5 15.55A19 19 0 0 1 48.45 22.5"
        fill="none"
        strokeWidth="6"
        strokeLinecap="round"
        className="stroke-running"
      />
    </>
  );
}

export interface LogoProps {
  /** Height in pixels. The mark is readable from 16 px. @default 32 */
  size?: number;
  className?: string;
  /** Accessible name; without one the logo is decorative. */
  label?: string;
}

/**
 * The Horva mark: a flat clock whose two hands at 10 and 2 form a check
 * mark. Ring and hands in `primary`, arc and pivot in `running`.
 */
export function HorvaMark({ size = 32, className, label }: LogoProps) {
  return (
    <svg
      viewBox="8 8 48 48"
      width={size}
      height={size}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={twMerge("shrink-0", className)}
    >
      <Clock />
      <path
        d="M26 27L32 34L40.5 21.5"
        fill="none"
        strokeWidth="5"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="stroke-primary"
      />
      <circle cx="32" cy="34" r="3.2" className="fill-running" />
    </svg>
  );
}

