export interface LoaderProps {
  /**
   * 16 in buttons, 20 to 32 in lists and cards, 64 for a whole page.
   * @default 24
   */
  size?: number;
  /**
   * Inside a filled button: ring and hands take the text color.
   * @default false
   */
  onFill?: boolean;
  /** @default 'Lädt' */
  label?: string;
  className?: string;
}

/**
 * The loading animation: the mark with turning hands. The minute hand
 * turns 12 times as fast as the hour hand. With reduced motion the hands
 * stand still as the check mark of the logo.
 */
export function Loader({
  size = 24,
  onFill = false,
  label = "Lädt",
  className,
}: LoaderProps) {
  const ink = onFill ? "stroke-current" : "stroke-primary";
  const hand =
    "origin-[32px_34px] [transform-box:view-box] motion-safe:animate-spin";
  return (
    <svg
      viewBox="8 8 48 48"
      width={size}
      height={size}
      role="img"
      aria-label={label}
      className={twMerge("shrink-0", className)}
    >
      <circle
        cx="32"
        cy="32"
        r="19"
        fill="none"
        strokeWidth="6"
        className={ink}
      />
      <path
        d="M22.5 15.55A19 19 0 0 1 48.45 22.5"
        fill="none"
        strokeWidth="6"
        strokeLinecap="round"
        className="stroke-running"
      />
      <path
        d="M32 34L26 27"
        fill="none"
        strokeWidth="5"
        strokeLinecap="round"
        className={twMerge(ink, hand, "[animation-duration:14.4s]")}
      />
      <path
        d="M32 34L40.5 21.5"
        fill="none"
        strokeWidth="5"
        strokeLinecap="round"
        className={twMerge(ink, hand, "[animation-duration:1.2s]")}
      />
      <circle cx="32" cy="34" r="3.2" className="fill-running" />
    </svg>
  );
}
